  {{ $entry := . }}{{ range .Resources.ByType "image" }}<p><img src="{{ (.Resize "1080x").Permalink }}" alt="{{ $entry.Title | htmlEscape }}" /></p>{{ end }}{{ .Content }}
  {{ range .Params.tags }}{{ . | htmlEscape }}{{ end }}

